   1 //! The one canonical registry endpoint, shared by config validation and release binding.
   2 
   3 use callisto_model::{CanonicalTranscript, RegistryBindingDigest, RegistryKey};
   4 
   5 /// Credential-free URL projection used only inside a digest transcript.
   6 #[derive(Debug, PartialEq, Eq)]
   7 pub(crate) struct RegistryBindingV1 {
   8     pub(crate) scheme: String,
   9     pub(crate) host: String,
  10     pub(crate) effective_port: Option<u16>,
  11     pub(crate) path: String,
  12 }
  13 
  14 impl RegistryBindingV1 {
  15     pub(crate) fn digest(&self) -> RegistryBindingDigest {
  16         let mut transcript = CanonicalTranscript::semantic_input_v1();
  17         transcript.push_str("registry.scheme", &self.scheme);
  18         transcript.push_str("registry.host", &self.host);
  19         transcript.push_str(
  20             "registry.port",
  21             &self.effective_port.map_or_else(String::new, |port| port.to_string()),
  22         );
  23         transcript.push_str("registry.path", &self.path);
  24         RegistryBindingDigest::from_normalized_binding(transcript.as_bytes())
  25     }
  26 
  27     pub(crate) fn endpoint(&self) -> String {
  28         let host = if self.host.contains(':') && !self.host.starts_with('[') {
  29             format!("[{}]", self.host)
  30         } else {
  31             self.host.clone()
  32         };
  33         let port = match (&self.scheme[..], self.effective_port) {
  34             ("https", Some(443)) | ("http", Some(80)) | (_, None) => String::new(),
  35             (_, Some(port)) => format!(":{port}"),
  36         };
  37         format!("{}://{host}{port}{}", self.scheme, self.path)
  38     }
  39 }
  40 
  41 /// Digest of a registry whose index is read at one endpoint and takes uploads at another.
  42 pub(crate) fn split_routes_digest(
  43     index: Option<&RegistryBindingV1>,
  44     upload: &RegistryBindingV1,
  45 ) -> RegistryBindingDigest {
  46     let mut transcript = CanonicalTranscript::semantic_input_v1();
  47     transcript.push_str(
  48         "registry.index",
  49         &index.map_or_else(String::new, RegistryBindingV1::endpoint),
  50     );
  51     transcript.push_str("registry.upload", &upload.endpoint());
  52     RegistryBindingDigest::from_normalized_binding(transcript.as_bytes())
  53 }
  54 
  55 /// Maps a `url::ParseError` to a specific, static diagnostic reason for
  56 /// [`GraphError::UnsafeRegistryBinding`]/[`GraphError::UnsafeGitRemote`],
  57 /// rather than discarding it behind one generic "invalid URL" message.
  58 pub(crate) fn url_parse_error_reason(error: url::ParseError) -> &'static str {
  59     match error {
  60         url::ParseError::RelativeUrlWithoutBase => "URL has no scheme (e.g. missing `https://`)",
  61         url::ParseError::EmptyHost => "URL host is empty",
  62         url::ParseError::InvalidPort => "URL port is invalid",
  63         url::ParseError::InvalidIpv4Address | url::ParseError::InvalidIpv6Address => {
  64             "URL host is not a valid IP address"
  65         }
  66         url::ParseError::InvalidDomainCharacter => "URL host contains an invalid character",
  67         url::ParseError::Overflow => "URL exceeds the maximum length",
  68         _ => "invalid URL",
  69     }
  70 }
  71 
  72 /// Cargo's `sparse+` marker on a registry index URL. Its presence is how cargo
  73 /// itself distinguishes an HTTP sparse index from a git index.
  74 pub(crate) const SPARSE_INDEX_PREFIX: &str = "sparse+";
  75 
  76 /// Canonicalises a registry URL (scheme/host case, default port, path) or names the unsafe part.
  77 pub(crate) fn canonical_registry_url(raw: &str) -> Result<RegistryBindingV1, &'static str> {
  78     let raw = raw.strip_prefix(SPARSE_INDEX_PREFIX).unwrap_or(raw);
  79     let parsed = url::Url::parse(raw).map_err(url_parse_error_reason)?;
  80     if parsed.cannot_be_a_base() || parsed.host_str().is_none() {
  81         return Err("URL must have an authority");
  82     }
  83     // A registry endpoint receives a credential, so cleartext discloses it; no loopback exception.
  84     if parsed.scheme() != "https" {
  85         return Err("registry URL scheme must be https");
  86     }
  87     if !parsed.username().is_empty() || parsed.password().is_some() {
  88         return Err("userinfo is forbidden");
  89     }
  90     if parsed.query().is_some() {
  91         return Err("query string is forbidden");
  92     }
  93     if parsed.fragment().is_some() {
  94         return Err("fragment is forbidden");
  95     }
  96     Ok(RegistryBindingV1 {
  97         scheme: parsed.scheme().to_ascii_lowercase(),
  98         host: parsed.host_str().expect("validated authority").to_ascii_lowercase(),
  99         effective_port: parsed.port_or_known_default(),
 100         path: parsed.path().to_string(),
 101     })
 102 }
 103 
 104 /// The URL a built-in registry key stands for when no `url` is configured.
 105 pub(crate) fn builtin_registry_url(key: &str) -> Option<&'static str> {
 106     match key {
 107         RegistryKey::CRATES_IO => Some("https://index.crates.io/"),
 108         RegistryKey::NPM => Some("https://registry.npmjs.org/"),
 109         RegistryKey::PYPI => Some("https://pypi.org/"),
 110         RegistryKey::NUGET => Some("https://api.nuget.org/v3/index.json"),
 111         _ => None,
 112     }
 113 }
