    // publish-exit knob the rig uses, preset in the script.
    let preset = if fail_cargo_publish {
        "CALLISTO_TEST_CARGO_PUBLISH_EXIT=23\n"
    } else {
        ""
    };
    fs::write(
        bin.join("cargo"),
        rig_cargo().replacen("#!/bin/sh\n", &format!("#!/bin/sh\n{preset}"), 1),
    )
    .unwrap();
