            publishers.log.with_extension("artifact-marker"),
        )
        .env("CALLISTO_TEST_FORGE_TAG", "core-crate@0.2.0")
        .env("CALLISTO_TEST_CARGO_MARKER", registry_marker(root))
        .env("CALLISTO_TEST_REAL_GIT", system_git())
